mapper.select:
select *
from sys_plugin_version
where plugin_code = #{pluginCode}
  and version = #{version}
  and deleted = 0
limit 1

mapper.insert:
insert into sys_plugin_dependency (
    plugin_code, depends_on_plugin_code, min_version, created_by, created_by_uuid, updated_by, updated_by_uuid, deleted
) values (
    #{entity.pluginCode}, #{entity.dependsOnPluginCode}, #{entity.minVersion},
    #{entity.createdBy}, #{entity.createdByUuid}, #{entity.updatedBy}, #{entity.updatedByUuid}, 0
)

mapper.delete:
delete from sys_plugin_permission_rel
where plugin_code = #{pluginCode}
  and plugin_version = #{version}

delete from sys_plugin_menu_rel
where plugin_code = #{pluginCode}
  and plugin_version = #{version}

mapper.select:
select plugin_code, plugin_version, menu_code, menu_name, route_path, icon, permission_key, parent_menu_code, sort_no
from sys_plugin_menu_rel
where plugin_code = #{pluginCode}
  and plugin_version = #{version}
  and deleted = 0
order by sort_no asc, id asc

select plugin_code, plugin_version, permission_key, permission_name, permission_group
from sys_plugin_permission_rel
where plugin_code = #{pluginCode}
  and plugin_version = #{version}
  and deleted = 0
order by id asc

select direction
from sys_plugin_schema_history
where plugin_code = #{pluginCode}
  and plugin_version = #{pluginVersion}
  and step_name = #{stepName}
  and execution_status = 'SUCCESS'
order by id desc
limit 1

mapper.insert:
insert into sys_plugin_schema_history (
    plugin_code, plugin_version, step_name, direction, script_path, execution_status, detail_message, created_by, created_by_uuid, created_at
) values (
    #{entity.pluginCode}, #{entity.pluginVersion}, #{entity.stepName}, #{entity.direction},
    #{entity.scriptPath}, #{entity.executionStatus}, #{entity.detailMessage}, #{entity.createdBy}, #{entity.createdByUuid}, current_timestamp
)

mapper.select:
select coalesce(max(operation_epoch), 0) + 1
from sys_plugin_migration_request
where plugin_code = #{pluginCode}

select *
from sys_plugin_migration_request
where plugin_code = #{pluginCode}
  and plugin_version = #{pluginVersion}
  and migration_digest = #{migrationDigest}
order by operation_epoch desc
limit 1
